use vstd::prelude::*;

verus! {
    fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> (result: Vec<i8>)
        requires
            numbers.len() <= 2 * (u32::MAX as usize), // Ensure the result can fit in memory
        ensures
            (numbers.len() == 0 ==> result.len() == 0) &&
            (numbers.len() == 1 ==> result.len() == 1 && result[0] == numbers[0]) &&
            (numbers.len() > 1 ==> result.len() == 2 * numbers.len() - 1) &&
            forall |i: usize| (i < numbers.len() ==> result[2 * i] == numbers[i]) &&
            forall |i: usize| (i < numbers.len() - 1 ==> result[2 * i + 1] == delimiter),
    {
        let n = numbers.len();
        if n == 0 {
            return vec![]; // Return empty vector for empty input
        } else if n == 1 {
            return vec![numbers[0]]; // Return unchanged for single element
        }

        let mut result: Vec<i8> = Vec::with_capacity(2 * n - 1);
        let mut i: usize = 0;

        while i < n
            invariant
                i <= n,
                result.len() == 2 * i - 1,
                result.len() <= 2 * n - 1,
                forall |j: usize| (j < i ==> result[2 * j] == numbers[j]) &&
                forall |j: usize| (j < i - 1 ==> result[2 * j + 1] == delimiter),
            decreases n - i,
        {
            result.push(numbers[i]); // Add the current number
            if i < n - 1 {
                result.push(delimiter); // Add the delimiter if not the last element
            }
            i = i + 1;
        }

        result
    }
}

